function alternatingSort(arr) {
  const result = [];
  const positives = arr.filter(n => n >= 0).sort((a, b) => a - b);
  const negatives = arr.filter(n => n < 0).sort((a, b) => b - a);
  let pi = 0, ni = 0;
  for (let i = 0; i < arr.length; i++) {
    if (i % 2 === 0 && pi < positives.length) result.push(positives[pi++]);
    else if (ni < negatives.length) result.push(negatives[ni++]);
    else if (pi < positives.length) result.push(positives[pi++]);
  }
  return result;
}
